#!/usr/bin/env bash
# Rebuilds x86sandbox/generated/ from the guest sources in x86sandbox/guest/.
#
# The guest (tiny386 plus the PE loader and Win32 layer) is compiled to wasm32,
# then wasm2c turns the Wasm module back into C. The generated C is checked in,
# so a normal Descent 3 build does not need this script or its tools.
#
# The generated C calls the wasm2c runtime in third_party/wasm2c, so it must be
# generated by wasm2c from the same WABT commit that runtime was copied from.
# This script builds wasm2c from a WABT checkout at that commit, and checks the
# checkout's runtime files against third_party/wasm2c.
#
# Requirements:
#   - clang and wasm-ld with the wasm32 target (CLANG, WASM_LD to override)
#   - WABT_DIR: a WABT git checkout at WABT_COMMIT below, for example
#       git clone https://github.com/WebAssembly/wabt && git -C wabt checkout <WABT_COMMIT>
#   - cmake and a C++ compiler to build wasm2c from it, and either OpenSSL's
#     headers (libssl-dev) or the checkout's third_party/picosha2 submodule
#
# Usage: WABT_DIR=<wabt checkout> x86sandbox/regenerate.sh

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/.." && pwd)"
CLANG="${CLANG:-clang}"
WASM_LD="${WASM_LD:-wasm-ld}"

# The WABT commit third_party/wasm2c was copied from. This commit is after the
# 1.0.42 release and has the table allocator fix for CVE-2026-90648; the 1.0.42
# release does not. Change it only together with third_party/wasm2c.
WABT_COMMIT=bda86b81e5b8dfcf75a4a5c1f7ad99c54254223f

# Total Wasm memory: guest memory (set by the host, 32 MiB by default) plus the
# sandbox's own heap. The memory never grows, so host pointers into it stay valid.
WASM_MEMORY_BYTES=$((64 * 1024 * 1024))

if [[ -z "${WABT_DIR:-}" ]]; then
  echo "regenerate.sh: set WABT_DIR to a WABT checkout at $WABT_COMMIT" >&2
  exit 1
fi
wabt_head="$(git -C "$WABT_DIR" rev-parse HEAD)"
if [[ "$wabt_head" != "$WABT_COMMIT" ]]; then
  echo "regenerate.sh: $WABT_DIR is at $wabt_head; it must be at $WABT_COMMIT" >&2
  exit 1
fi
for f in "$root"/third_party/wasm2c/*; do
  name="$(basename "$f")"
  if [[ "$name" == LICENSE ]]; then
    upstream="$WABT_DIR/LICENSE"
  else
    upstream="$WABT_DIR/wasm2c/$name"
  fi
  if ! cmp -s "$f" "$upstream"; then
    echo "regenerate.sh: third_party/wasm2c/$name differs from $upstream" >&2
    exit 1
  fi
done

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

# wasm2c, built from the checkout
cmake -S "$WABT_DIR" -B "$work/wabt-build" -DCMAKE_BUILD_TYPE=Release -DBUILD_TESTS=OFF -DBUILD_LIBWASM=OFF \
  -DBUILD_FUZZ_TOOLS=OFF > "$work/wabt-configure.log"
cmake --build "$work/wabt-build" --target wasm2c --parallel > "$work/wabt-build.log"
WASM2C="$work/wabt-build/wasm2c"
version="$("$WASM2C" --version)"

# -ffile-prefix-map keeps the checkout's location out of the output (__FILE__ is
# used in tiny386's messages), so the result is the same wherever it is built.
cflags=(
  --target=wasm32 -O2 -ffreestanding -nostdlib -fno-builtin -Wall -Werror
  -ffile-prefix-map="$root/="
  -I"$here/guest/libc" -I"$here/guest" -I"$root/third_party/tiny386"
)

objs=()
for src in sandbox.c win32.c libc.c cpu_glue.c fpu_glue.c; do
  obj="$work/${src%.c}.o"
  # tiny386's own files produce warnings we do not control.
  if [[ $src == cpu_glue.c || $src == fpu_glue.c ]]; then
    "$CLANG" "${cflags[@]}" -Wno-error -w -c "$here/guest/$src" -o "$obj"
  else
    "$CLANG" "${cflags[@]}" -c "$here/guest/$src" -o "$obj"
  fi
  objs+=("$obj")
done

"$WASM_LD" --no-entry --strip-debug \
  --initial-memory=$WASM_MEMORY_BYTES --max-memory=$WASM_MEMORY_BYTES \
  -z stack-size=1048576 \
  "${objs[@]}" -o "$work/x86sandbox.wasm"

"$WASM2C" "$work/x86sandbox.wasm" --module-name=x86sandbox -o "$work/x86sandbox_wasm.c"

mkdir -p "$here/generated"
cp "$work/x86sandbox_wasm.c" "$work/x86sandbox_wasm.h" "$here/generated/"
{
  echo "Generated by x86sandbox/regenerate.sh. Do not edit."
  echo "wasm2c: $version, built from WABT $WABT_COMMIT"
  echo "clang: $("$CLANG" --version | head -n1)"
} > "$here/generated/README.txt"

# Read back what was produced: the module must not import anything we do not provide.
imports="$(grep -oE '^[a-z0-9_]+ w2c_env_[a-z0-9_]+\(' "$here/generated/x86sandbox_wasm.h" | sed -E 's/^[a-z0-9_]+ //; s/\($//' | sort -u)"
expected="w2c_env_fmt_double
w2c_env_host_call
w2c_env_host_log
w2c_env_host_time_ms
w2c_env_m_acos
w2c_env_m_asin
w2c_env_m_atan
w2c_env_m_atan2
w2c_env_m_cos
w2c_env_m_exp
w2c_env_m_fmod
w2c_env_m_log
w2c_env_m_log10
w2c_env_m_log2
w2c_env_m_pow
w2c_env_m_sin
w2c_env_m_tan
w2c_env_parse_double"
if [[ "$imports" != "$expected" ]]; then
  echo "regenerate.sh: unexpected import set:" >&2
  diff <(echo "$expected") <(echo "$imports") >&2 || true
  exit 1
fi
echo "regenerated $here/generated ($(wc -c < "$here/generated/x86sandbox_wasm.c") bytes of C)"
